class InvalidInputError(Exception):
    pass

class Solution(object):
    def repeatedNTimes(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        n = len(nums) // 2
        if len(nums) % 2 != 0 or len(set(nums)) != n + 1:
            raise InvalidInputError("Input array length must be 2N and contain N+1 unique elements.")

        seen = set()
        for num in nums:
            if num in seen:
                return num
            seen.add(num)

        raise InvalidInputError("No element repeated N times found.")
